*{box-sizing:border-box}body{margin:0;background:#f3f0e5;color:var(--ink);font-family:Nunito, sans-serif;font-size:14px;min-height:100vh;background-image:radial-gradient(ellipse at 2% 15%,rgba(228,215,179,.26),transparent 30%),radial-gradient(ellipse at 94% 85%,rgba(210,221,190,.25),transparent 32%)}button{font:inherit;color:inherit;cursor:pointer}button:focus-visible,a:focus-visible,canvas:focus-visible{outline:3px solid #d59d68;outline-offset:3px}.app-shell{max-width:1460px;margin:0 auto;padding:0 40px 32px;position:relative;overflow:hidden}.topbar{height:92px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(89,122,79,.16);position:relative;z-index:2}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:var(--ink);min-width:250px}.brand-mark{height:44px;width:44px;border-radius:14px;background:#e6ead7;display:grid;place-items:center;box-shadow:inset 0 0 0 1px rgba(67,92,55,.07)}.brand-mark svg{width:32px;fill:none;stroke:#56784d;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}.brand-mark .sun{stroke:#d69b58;stroke-width:2}.brand-copy{display:grid;line-height:1}.brand-copy strong{font:600 24px/1 Fraunces,serif;letter-spacing:-.7px}.brand-copy small{font-size:8px;letter-spacing:1.55px;font-weight:800;color:#8a9981;margin-top:6px}.top-status{display:flex;gap:9px;align-items:center}.day-pill,.clock-pill,.weather-pill{height:38px;border:1px solid #e8e4d7;border-radius:22px;background:rgba(255,253,245,.75);display:flex;align-items:center;padding:0 13px;gap:7px;color:#66745e;font-size:12px;font-weight:700}.sun-icon{font-size:16px;color:#d2934d}.clock-icon{font-size:17px;color:#77876e}.weather-pill{padding-right:15px}.weather-pill span:first-child{color:#d39a55;font-size:15px}.wallet{display:flex;align-items:center;gap:9px;min-width:145px;justify-content:flex-end}.wallet>div{display:grid;line-height:1.1}.wallet small{font-size:8px;letter-spacing:1.4px;color:#92a087;font-weight:800}.wallet strong{font:600 22px/1.1 Fraunces,serif;margin-top:3px}.coin-icon{color:#d69a4e;font-size:18px}.market-shortcut{border:0;background:#e9eddf;color:#57754e;border-radius:50%;height:28px;width:28px;font-size:16px;margin-left:3px}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 278px;gap:26px;padding-top:22px;align-items:stretch}.farm-column{min-width:0}.scene-wrap{width:100%;position:relative;border-radius:17px;overflow:hidden;box-shadow:0 12px 30px rgba(63,77,49,.16),0 0 0 1px rgba(62,76,45,.12);background:#83a968}.scene-wrap:after{content:"";position:absolute;inset:0;border:1px solid rgba(255,255,255,.4);border-radius:17px;pointer-events:none}#farm{display:block;width:100%;height:auto;aspect-ratio:13/9;object-fit:contain;touch-action:none}.scene-label{position:absolute;top:15px;left:16px;display:flex;align-items:center;gap:7px;border-radius:20px;background:rgba(252,249,235,.93);padding:7px 11px;font-size:9px;font-weight:800;letter-spacing:1.25px;color:#697b5d;box-shadow:0 2px 6px #475d3626}.pin{font-size:15px;color:#bf8760}.canvas-help{position:absolute;bottom:13px;left:50%;transform:translateX(-50%);white-space:nowrap;padding:6px 11px;border-radius:20px;background:rgba(44,63,41,.70);color:#fff9e6;font-size:10px;font-weight:600;letter-spacing:.1px;opacity:.86}.canvas-help i{font-style:normal;color:#e3c18e;margin:0 4px}.keycap,kbd{font-family:Nunito,sans-serif;font-size:9px;font-weight:800;border-radius:4px;padding:1px 5px;background:rgba(255,255,255,.2);color:inherit}.toast{position:absolute;top:16px;left:50%;transform:translate(-50%,-10px);opacity:0;pointer-events:none;padding:9px 16px;border-radius:22px;background:#fff9e7;color:#496246;font-weight:800;font-size:12px;box-shadow:0 5px 16px #32432d36;transition:opacity .2s,transform .2s;white-space:nowrap;z-index:3}.toast.show{opacity:1;transform:translate(-50%,0)}.farm-controls{display:flex;align-items:stretch;gap:10px;margin-top:13px}.tools{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;flex:1}.tool{height:66px;display:flex;align-items:center;text-align:left;gap:9px;background:rgba(255,253,246,.86);border:1px solid #e7e2d5;border-radius:12px;padding:0 9px;position:relative;transition:transform .15s,background .15s,border .15s;box-shadow:0 2px 5px rgba(63,77,49,.025)}.tool:hover{transform:translateY(-2px);border-color:#b9c9a9}.tool.active{background:#edf1e4;border-color:#94a984;box-shadow:inset 0 0 0 1px #e1e9d8}.tool-art{height:36px;width:34px;border-radius:10px;display:grid;place-items:center;font-size:24px;flex:0 0 auto;background:#f0e9d5;color:#8b7654}.seed-art{background:#f0ead4;color:#738351}.water-art{background:#e2eee9;color:#7199a1}.harvest-art{background:#f6e5d6;color:#c5834a}.tool-info{display:flex;min-width:0;flex-direction:column;line-height:1.1}.tool-info b{font-size:12px;font-weight:800}.tool-info small{color:#85917c;font-size:9px;margin-top:4px;white-space:nowrap}.tool-info kbd{background:#e6e5d9;color:#829078;margin-left:3px;padding:0 4px}.tool-count{margin-left:auto;align-self:flex-start;margin-top:10px;color:#89967f;font-size:10px;font-weight:800}.new-badge{font-size:7px;letter-spacing:.6px;color:#bb724b;font-weight:800;margin-top:2px}.sleep-button{width:155px;border:1px solid #55724d;background:#5a7950;color:#fff9e9;border-radius:12px;display:flex;align-items:center;gap:8px;padding:0 9px;box-shadow:0 3px 8px #55724d25}.sleep-button:hover{background:#486c46}.sleep-button .moon{font-size:22px;color:#f1d59a}.sleep-button span:nth-child(2){display:grid;text-align:left;line-height:1.12;flex:1}.sleep-button b{font-size:11px}.sleep-button small{font-size:9px;color:#dce7cf;margin-top:3px}.sleep-button kbd{background:#ffffff24}.side-panel{display:flex;flex-direction:column;gap:12px}.welcome-card{min-height:228px;border-radius:15px;padding:18px 19px 16px;background:#e9eddf;border:1px solid #dce3d0;position:relative;overflow:hidden}.welcome-card:after{content:"";position:absolute;right:-20px;top:68px;width:130px;height:130px;border-radius:50%;border:1px solid #d7dfca;box-shadow:0 0 0 12px #e1e8d7,0 0 0 25px #e5ebdc;opacity:.7}.welcome-top{display:flex;justify-content:space-between;align-items:center}.eyebrow{font-size:9px;font-weight:800;letter-spacing:1.5px;color:#7e9270}.leaf-stamp{color:#d19356;font-size:24px;line-height:1}.welcome-card h1{font:600 30px/1.02 Fraunces,serif;letter-spacing:-.7px;margin:13px 0 7px;color:#384b37;position:relative;z-index:1}.welcome-card h1 em{font-weight:600;color:#71855f}.welcome-card p{max-width:190px;margin:0;color:#778570;font-size:11px;line-height:1.4;position:relative;z-index:1}.quest-progress{position:relative;z-index:1;margin-top:20px}.quest-line{display:flex;justify-content:space-between;align-items:center;font-size:8px;letter-spacing:1px;color:#79886e;font-weight:800}.quest-line b{font-size:10px;letter-spacing:0;color:#526849}.progress-track{height:6px;margin-top:7px;border-radius:8px;background:#d6dfcd;overflow:hidden}.progress-track i{display:block;width:0;height:100%;background:#c98c55;border-radius:8px;transition:width .3s}.inventory-card{background:rgba(255,253,246,.84);border:1px solid #e9e4d8;border-radius:15px;padding:15px 16px 13px}.section-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px}.section-heading h2{margin:0;font:600 18px/1 Fraunces,serif;color:#40513d}.inventory-cap{font-size:8px;font-weight:800;letter-spacing:1.3px;color:#a0a58e}.inventory-row{height:40px;border-top:1px solid #efecdf;display:flex;align-items:center;gap:9px}.item-icon{width:25px;height:25px;border-radius:8px;display:grid;place-items:center;font-size:18px}.carrot-icon{background:#f5e8d7;color:#c98149}.produce-icon{background:#e9eedf;color:#759250}.item-name{font-size:11px;font-weight:700;color:#697763;flex:1}.inventory-row b{font:600 16px/1 Fraunces,serif;color:#435340}.inventory-row small{width:36px;text-align:right;font-size:9px;color:#a1a48f}.sell-button{border:0;border-radius:9px;height:34px;width:100%;padding:0 10px;background:#f2eee0;color:#637453;display:flex;align-items:center;justify-content:space-between;font-size:10px;font-weight:800;margin-top:4px}.sell-button:hover{background:#e8eadc}.sell-button span:last-child{color:#b17c4d;font-size:9px}.market-note{margin:8px 0 0;text-align:center;font-size:9px;color:#a0a28e}.market-note span{color:#d19a57}.field-note{display:flex;gap:11px;border-radius:12px;border:1px dashed #d9d9c8;padding:11px 12px;background:rgba(251,249,239,.58);min-height:78px}.note-icon{height:27px;width:27px;flex:0 0 auto;border-radius:8px;background:#eee9d9;display:grid;place-items:center;color:#aa8d64;font-size:15px}.field-note h3{margin:0 0 3px;font:600 14px/1.2 Fraunces,serif;color:#586b4d}.field-note p{margin:0;color:#83907a;font-size:10px;line-height:1.35}.day-footer{display:flex;align-items:center;gap:6px;margin:auto 3px 0;color:#a2a691;font-size:9px;letter-spacing:.3px}.tiny-sun{font-size:17px;color:#d09a58}.footer-heart{margin-left:auto;color:#bf8972}.touch-controls{display:none}.screen-grain{position:fixed;inset:0;pointer-events:none;z-index:10;opacity:.035;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.4'/%3E%3C/svg%3E")}.market-dialog{width:min(410px,calc(100% - 28px));border:1px solid #e2ddce;border-radius:20px;padding:28px 30px 22px;background:#fffdf4;color:var(--ink);box-shadow:0 25px 80px #26332340;text-align:center}.market-dialog::backdrop{background:#26332366;backdrop-filter:blur(3px)}.dialog-close{position:absolute;right:13px;top:12px;border:0;background:#f1efe4;color:#73806b;border-radius:50%;width:29px;height:29px;font-size:21px;line-height:1}.market-illustration{margin:0 auto 8px;width:54px;height:54px;border-radius:17px;background:#f5ead7;display:grid;place-items:center;font-size:29px}.market-dialog .eyebrow{font-size:8px}.market-dialog h2{font:600 26px/1.15 Fraunces,serif;margin:8px 0;color:#455540}.dialog-copy{font-size:12px;color:#828a77;line-height:1.5;margin:0 auto 19px;max-width:300px}.market-deal{display:flex;align-items:center;text-align:left;border:1px solid #ece8db;border-radius:12px;padding:10px;gap:10px}.deal-icon{display:grid;place-items:center;width:36px;height:36px;border-radius:10px;background:#eff0df;color:#788956;font-size:24px}.market-deal div{display:grid;flex:1}.market-deal b{font-size:11px;color:#56664d}.market-deal small{font-size:9px;color:#969b88;margin-top:3px}.market-deal strong{font:600 16px Fraunces,serif;color:#bd8751}.market-deal strong small{font:700 8px Nunito;color:#a29e89}.buy-button,.dialog-sell{width:100%;height:41px;border-radius:10px;margin-top:9px;display:flex;justify-content:space-between;align-items:center;padding:0 13px;font-size:11px;font-weight:800}.buy-button{background:#59784e;color:#fff9ec;border:0}.buy-button:hover{background:#486d46}.buy-button span{color:#f0d7a8}.dialog-sell{background:#f1eee2;border:1px solid #e9e4d7;color:#748068}.market-flavor{font:italic 11px Fraunces,serif;color:#a39074;margin:16px 0 0}
