ry-row b{font-size:14px}.inventory-row small{font-size:8px;width:29px}.sell-button{height:30px;font-size:9px;padding:0 7px}.sell-button span:last-child{font-size:8px}.market-note{font-size:8px;margin-top:5px}.field-note{min-height:65px;padding:8px;gap:7px;border-radius:10px}.field-note h3{font-size:12px}.field-note p{font-size:9px}.note-icon{width:23px;height:23px;font-size:13px}.day-footer{display:none}.touch-controls{display:flex;position:fixed;z-index:5;right:10px;bottom:calc(10px + env(safe-area-inset-bottom));align-items:center;gap:5px;opacity:.94}.touch-controls>div{display:grid;grid-template-columns:repeat(3,34px);grid-template-rows:repeat(2,31px);gap:3px}.touch-controls>div button{border:1px solid #e4dfd0;background:#fffdf1e8;border-radius:8px;color:#59744c;font-size:16px;font-weight:800;box-shadow:0 2px 4px #39432c20;touch-action:none}.touch-controls>div button[data-move=up]{grid-column:2}.touch-controls>div button[data-move=left]{grid-column:1;grid-row:2}.touch-controls>div button[data-move=down]{grid-column:2;grid-row:2}.touch-controls>div button[data-move=right]{grid-column:3;grid-row:2}.touch-use{height:38px;padding:0 10px;border:1px solid #55724d;border-radius:9px;background:#59784e;color:#fff;font-size:9px;font-weight:800;touch-action:none}.screen-grain{display:none}}
@media(max-width:390px){.app-shell{padding-left:8px;padding-right:8px}.brand-copy small{display:none}.top-status .clock-pill{display:none}.tool{gap:3px;padding:0 3px}.tool-art{height:24px;width:22px}.tool-info small{font-size:6px}.sleep-button{width:103px}.side-panel{gap:6px}.welcome-card{padding:10px}.welcome-card h1{font-size:22px}.welcome-card p{font-size:9px}}

